entries[50734] = { ["name"] = "Königliches Szepter von Terenas II", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nWaffenhand Streitkolben\n333 - 619 Schaden Tempo 1.80\n(264.44 Schaden pro Sekunde)\n+152 Ausdauer\n\nRoter Sockel\nSockelbonus: +5 Zaubermacht\n\nHaltbarkeit 105 / 105\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 55.\nAnlegen: Erhöht die Tempowertung um 71.\nAnlegen: Erhöht die Zaubermacht um 1.118.\n\"Obwohl es zerbrochen und verderbt ist, könnt Ihr noch immer das königliche Siegel von Lordaeron erkennen.\"\nVerkaufspreis:" }
entries[50735] = { ["name"] = "Schwurbinder, Kraft des Waldläufergenerals", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nZweihändig Stangenwaffe\n1,001 - 1,502 Schaden Tempo 3.60\n(347.64 Schaden pro Sekunde)\n+179 Beweglichkeit\n+269 Ausdauer\n\nRoter Sockel\nBlauer Sockel\nGelber Sockel\nSockelbonus: +8 Beweglichkeit\n\nHaltbarkeit 120 / 120\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 114.\nAnlegen: Erhöht die Tempowertung um 122.\n\"Ein grotesker Schädel ziert nun den Griff der Schneide. In den Axtkopf wurde zehnmal mit Blut das gleiche Wort geätzt: LEIDET.\"\nVerkaufspreis:" }
